#include <cstdio>
#include <vector>
#include <queue>
#include <functional>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) scanf("%d", &a[i]);

    std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
    for (int x : a) {
        pq.push(x);
        if ((int)pq.size() > k) pq.pop();
    }
    printf("%d\n", pq.top());
    return 0;
}
